    # 7-9 (+ day)
    h = mv.doc["hands"]
    want = {"hour": F(-1, 12), "minute": F(-1), "seconds": F(-60), "day": F(-1, 24)}
    for key, cid in (("hour", "7"), ("minute", "8"), ("seconds", "9"), ("day", "P2.1")):
        if key not in h or h[key] is None:
            R[cid] = (False, "absent")
            continue
        got = sp.get(h[key]["mobile"])
        R[cid] = (got == want[key] and not conflict, str(got))
    # 10
    R["10"] = (np.hypot(*(np.array(mv.axis[h["hour"]["mobile"]]) - np.array(mv.axis[h["minute"]["mobile"]]))) <= 0.01, None)
    # 11 + day placement
    ftop = max(mv.parts[n].bounding_box()[5] for n in mv.fixed)
    out = {}
    for key, reach in (("hour", 5), ("minute", 5), ("seconds", 5), ("day", 3)):
        e = h[key]
        man = mv.parts[e["part"]]
        c = np.array(mv.axis[e["mobile"]])
        v = kernel.verts(man)
        rmax = np.hypot(v[:, 0] - c[0], v[:, 1] - c[1]).max()
        low = man.bounding_box()[2]
        # centroid of volume
        mesh = man.to_mesh()
        vp = np.asarray(mesh.vert_properties)[:, :3]
        tt = vp[np.asarray(mesh.tri_verts)]
        vol6 = np.einsum("ij,ij->i", tt[:, 0], np.cross(tt[:, 1], tt[:, 2]))
        cen = (vol6[:, None] * tt.sum(1)).sum(0) / (4 * vol6.sum())
        cd = np.hypot(cen[0] - c[0], cen[1] - c[1])
        out[key] = (rmax >= reach and low >= ftop - 1e-9 and cd >= 0.5, round(rmax, 3), round(low, 3), round(cd, 3))
    R["11"] = (all(out[k][0] for k in ("hour", "minute", "seconds")), out, "frame top", ftop)
    dax = np.hypot(*(np.array(mv.axis[h["day"]["mobile"]]) - np.array(mv.axis[h["hour"]["mobile"]])))
    R["P2.2"] = (out["day"][0] and dax >= 6, round(dax, 3))
    # 12
    cc = np.array(mv.doc["case_centre"])
    worst = 0
    for n in mv.fixed:
        v = kernel.verts(mv.parts[n])
        worst = max(worst, np.hypot(v[:, 0] - cc[0], v[:, 1] - cc[1]).max())
    for k in names:
        v = kernel.verts(mv.mob[k])
        c = np.array(mv.axis[k])
        worst = max(worst, np.hypot(v[:, 0] - c[0], v[:, 1] - c[1]).max() + np.hypot(*(c - cc)))
    allm = U([mv.frame] + list(mv.mob.values()))
    bb = allm.bounding_box()
    R["12"] = (worst <= R_CASE and bb[5] - bb[2] <= H_CASE, round(worst, 3), round(bb[5] - bb[2], 3))
    # 14
    Y = lewis()
    path = rated_path(mv, passing, h["seconds"]["mobile"])
    bad = []
    info = []
    if path is None:
        bad.append("seconds not reached")
    else:
        for i in path:
            e = mv.meshes[i]
            ok, det = res[(i, 0.0)]
            Dn, Nn = e["driver"], e["driven"]
            TD = T_BARREL * abs(sp["barrel"] / sp[Dn])
            m = det["m"]
            Fz = float(TD) / (m * e["driver_teeth"] / 2)
            b = det["b"]
            for g, z in ((Dn, e["driver_teeth"]), (Nn, e["driven_teeth"])):
                if g == "barrel":
                    continue
                sig = Fz / (b * m * Y[z])
                al = ALLOW[mv.doc["mobiles"][g]["material"]]
                info.append((Dn, Nn, g, z, round(sig, 1), al))
                if sig > al:
                    bad.append((g, sig))
    R["14"] = (not bad, info, bad)
    for k in sorted(R):
        print(k, R[k])
    print("elapsed", round(time.time() - t0))
    return R


def rated_path(mv, passing, target):
    adj = {}
    for i, e in enumerate(mv.meshes):
        if passing.get(i):
            adj.setdefault(e["driver"], []).append((e["driven"], i))
            adj.setdefault(e["driven"], []).append((e["driver"], i))
    prev = {"barrel": None}
    q = ["barrel"]
    while q:
        x = q.pop(0)
        for y, i in adj.get(x, []):
            if y not in prev:
                prev[y] = (x, i)
                q.append(y)
    if target not in prev:
        return None
    path = []
    x = target
    while prev[x] is not None:
        x, i = prev[x]
        path.append(i)
    return path[::-1]


def printability(fname):
    from printcheck import printable
    doc = json.load(open(os.path.join(DELIV, fname)))
    names = list(doc["fixed"]) + [p for m in doc["mobiles"].values() for p in m["parts"]]
    for n in names:
        t = time.time()
        print("13", n, printable(load(n)), round(time.time() - t, 1), flush=True)


if __name__ == "__main__":
    fname = sys.argv[1] if len(sys.argv) > 1 else "movement.json"
    cls = sys.argv[2] if len(sys.argv) > 2 else "D"
    what = sys.argv[3] if len(sys.argv) > 3 else "part1"
    if what == "part1":
        part1(fname, cls)
    elif what == "print":
        printability(fname)

