"""Self-check of the delivery against QA-W100 rev A (our own reading of it).
python3 inspect_qa.py [movement.json|variant_6h.json] [--class D|B] [--only checks] [--assembly]"""
import json
import math
import os
import pickle
import sys
import time
from fractions import Fraction as F
from concurrent.futures import ProcessPoolExecutor

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
DELIV = os.path.dirname(HERE)
APP = os.path.dirname(DELIV)
sys.path.insert(0, os.path.join(APP, "tools"))
sys.path.insert(0, HERE)
import kernel  # noqa: E402
import manifold3d as m3  # noqa: E402

CACHE = os.environ.get("QA_CACHE", "/tmp/qa_cache")
TOL = 0.01
R_CASE, H_CASE = 20.7, 13.4
T_BARREL = 70.1
ALLOW = {"AD-C100-HT": 725.0, "AD-CW614N": 110.0}
SPEED = {"D": F(-1, 8), "B": F(-1, 6)}       # turns per hour, CCW positive


def lewis():
    txt = open(os.path.join(APP, "datasheets", "DS-W04_gear_rating.md")).read().split("## 3.")[1]
    Y = {}
    for line in txt.splitlines():
        c = [x.strip() for x in line.strip().strip("|").split("|")]
        if len(c) == 11 and c[0].isdigit():
            for j in range(10):
                if c[j + 1] not in ("–", "-", ""):
                    Y[int(c[0]) + j] = float(c[j + 1])
    return Y


def load(name):
    p = os.path.join(DELIV, "parts", name + ".step")
    os.makedirs(CACHE, exist_ok=True)
    key = os.path.join(CACHE, "%s_%d_%d.pkl" % (name, os.path.getsize(p), int(os.path.getmtime(p))))
    if os.path.exists(key):
        v, t = pickle.load(open(key, "rb"))
        return m3.Manifold(m3.Mesh(vert_properties=v, tri_verts=t))
    man = kernel.load_step_part(p, 16777216, 200000, 0.001, 0.1, 500, 120, 4096, 0.005)
    mesh = man.to_mesh()
    pickle.dump((np.asarray(mesh.vert_properties), np.asarray(mesh.tri_verts)), open(key, "wb"))
    return man


def barrel():
    t = kernel.read_stl(os.path.join(APP, "supplied", "barrel.stl"), 10 ** 7, 10 ** 9)
    return kernel.tris_to_manifold(t)


def rotz(man, c, deg):
    a = math.radians(deg)
    cs, sn = math.cos(a), math.sin(a)
    T = np.array([[cs, -sn, 0, c[0] - cs * c[0] + sn * c[1]], [sn, cs, 0, c[1] - sn * c[0] - cs * c[1]], [0, 0, 1, 0]])
    return man.transform(T.tolist())


def tr(man, d):
    return man.translate(list(map(float, d)))


def U(lst):
    return kernel.union(list(lst))


class Mv:
    def __init__(self, fname, cls):
        self.doc = json.load(open(os.path.join(DELIV, fname)))
        self.cls = cls
        d = self.doc
        self.parts = {}
        names = list(d["fixed"]) + [p for m in d["mobiles"].values() for p in m["parts"]]
        for n in names:
            self.parts[n] = load(n)
        self.fixed = d["fixed"]
        self.frame = U(self.parts[n] for n in self.fixed)
        self.mob = {"barrel": barrel()}
        self.axis = {"barrel": (0.0, 0.0)}
        self.mparts = {"barrel": ["barrel"]}
        self.parts["barrel"] = self.mob["barrel"]
        for k, m in d["mobiles"].items():
            self.mob[k] = U(self.parts[p] for p in m["parts"])
            self.axis[k] = tuple(m["axis"])
            self.mparts[k] = m["parts"]
        self.meshes = d["meshes"]


# ---------------- mesh test ----------------
def mesh_test(Dm, Dc, zD, Nm, Nc, zN, a_assembled, shift=0.0):
    """Returns (ok, details). shift: N moved along D->N line (+ away)."""
    Nc = np.array(Nc, float)
    Dc = np.array(Dc, float)
    v = Nc - Dc
    dist = np.hypot(*v)
    u = v / dist if dist > 0.01 else np.array([1.0, 0.0])
    Nm0 = tr(Nm, [u[0] * shift, u[1] * shift, 0]) if shift else Nm
    Ncs = Nc + u * shift
    m = 2 * a_assembled / (zD + zN)
    nsteps = 8 * max(zD, zN)
    worst_ov, worst_ratio, worst_gap, minV, minH = 0.0, 1e9, 0.0, 1e9, 1e9

    def pose(i):
        ang = i * 360.0 / (8 * zD)
        return rotz(Dm, Dc, ang), rotz(Nm0, Ncs, -ang * zD / zN), ang
    for i in range(nsteps):
        Dr, Nr, ang = pose(i)
        ov = kernel.ivol(Dr, Nr)
        worst_ov = max(worst_ov, ov)
        if i % 8 == 0:
            for fr in (1 / 3, 1 / 5):
                Da, Na, _ = pose(i + fr)
                worst_ov = max(worst_ov, kernel.ivol(Da, Na))
            D2 = rotz(Dm, Dc, ang + 90.0 / zD)
            reg = (D2 ^ Nr) - Dr
            V = reg.volume()
            if V > 0:
                bb = reg.bounding_box()
                H = bb[5] - bb[2]
            else:
                H = 0.0
            minV = min(minV, V)
            if H > 0:
                minH = min(minH, H)
                worst_ratio = min(worst_ratio, (V / H) / (0.5 * m * m))
            else:
                worst_ratio = 0.0
        if i % 4 == 0 and ov <= 1e-12:
            g = kernel.min_distance(Dr, Nr, 0.5)
            worst_gap = max(worst_gap, g)
    ok = worst_ov <= TOL and worst_gap <= 0.1 and minV >= 0.001 and worst_ratio > 1.0
    return ok, dict(ov=round(worst_ov, 5), gap=round(worst_gap, 4), minV=round(minV, 5), ratio=round(worst_ratio, 3),
                    b=round(minH, 4), m=round(m, 5))


def _mesh_job(args):
    fname, cls, idx, shift = args
    mv = Mv(fname, cls)
    e = mv.meshes[idx]
    Dn, Nn = e["driver"], e["driven"]
    a = float(np.hypot(*(np.array(mv.axis[Nn]) - np.array(mv.axis[Dn]))))
    t = time.time()
    ok, det = mesh_test(mv.mob[Dn], mv.axis[Dn], e["driver_teeth"], mv.mob[Nn], mv.axis[Nn], e["driven_teeth"], a, shift)
    det["t"] = round(time.time() - t, 1)
    return idx, shift, ok, det


def speeds(mv, passing):
    sp = {"barrel": SPEED[mv.cls]}
    bad = False
    changed = True
    while changed:
        changed = False
        for i, e in enumerate(mv.meshes):
            if not passing.get(i, False):
                continue
            Dn, Nn, zD, zN = e["driver"], e["driven"], e["driver_teeth"], e["driven_teeth"]
            for a, b, za, zb in ((Dn, Nn, zD, zN), (Nn, Dn, zN, zD)):
                if a in sp:
                    v = -sp[a] * F(za, zb)
                    if b in sp and sp[b] != v:
                        bad = True
                    elif b not in sp:
                        sp[b] = v
                        changed = True
    return sp, bad


def _pair_job(args):
    fname, cls, a, b, sa, sb = args
    mv = Mv(fname, cls)
    A, B = mv.mob[a], mv.mob[b]
    ca, cb = mv.axis[a], mv.axis[b]
    worst = 0.0
    fa, fb = abs(float(sa)), abs(float(sb))
    poses = []
    if fa == 0 and fb == 0:
        poses = [(0.0, 0.0)]
    else:
        fast = max(fa, fb)
        T = 1.0 / fast
        for k in range(144):
            t = T * k / 144
            poses.append((360 * float(sa) * t, 360 * float(sb) * t))
        if sa != sb:
            rel = abs(float(sa - sb))
            T2 = 1.0 / rel
            for k in range(144):
                t = T2 * k / 144
                poses.append((360 * float(sa) * t, 360 * float(sb) * t))
    for pa, pb in poses:
        worst = max(worst, kernel.ivol(rotz(A, ca, pa), rotz(B, cb, pb)))
    return a, b, worst


def part1(fname, cls, jobs=4, skip=()):
    t0 = time.time()
    mv = Mv(fname, cls)
    R = {}
    names = list(mv.mob)
    # C2
    c2 = []
    for k in names:
        v = kernel.ivol(mv.frame, mv.mob[k])
        if v > TOL:
            c2.append("frame x %s %.4f" % (k, v))
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            v = kernel.ivol(mv.mob[names[i]], mv.mob[names[j]])
