    fx = mv.fixed
    for i in range(len(fx)):
        for j in range(i + 1, len(fx)):
            v = kernel.ivol(mv.parts[fx[i]], mv.parts[fx[j]])
            if v > TOL:
                c2.append("fixed %s x %s %.4f" % (fx[i], fx[j], v))
    for k in names:
        ps = mv.mparts[k]
        for i in range(len(ps)):
            for j in range(i + 1, len(ps)):
                v = kernel.ivol(mv.parts[ps[i]], mv.parts[ps[j]])
                if v > TOL:
                    c2.append("in %s: %s x %s %.4f" % (k, ps[i], ps[j], v))
    # frame connectivity
    joined = {fx[0]}
    changed = True
    while changed:
        changed = False
        for a in fx:
            if a in joined:
                continue
            for b in list(joined):
                if kernel.min_distance(mv.parts[a], mv.parts[b], 0.05) <= 0.01:
                    joined.add(a)
                    changed = True
                    break
    if len(joined) != len(fx):
        c2.append("frame not joined: %s" % (set(fx) - joined))
    R["C2"] = (not c2, c2)
    print("C2", R["C2"], round(time.time() - t0), flush=True)
    # 1 free to turn
    bad = []
    for k in names:
        w = max(kernel.ivol(mv.frame, rotz(mv.mob[k], mv.axis[k], 5 * s)) for s in range(72))
        if w > TOL:
            bad.append((k, w))
    R["1"] = (not bad, bad)
    print("1", R["1"], flush=True)
    # 2 held
    dirs = {"+x": (0.3, 0, 0), "-x": (-0.3, 0, 0), "+y": (0, 0.3, 0), "-y": (0, -0.3, 0), "+z": (0, 0, 0.3), "-z": (0, 0, -0.3)}
    notheld = []
    for dn, dv in dirs.items():
        held = {k: kernel.ivol(mv.frame, tr(mv.mob[k], dv)) > TOL for k in names}
        changed = True
        while changed:
            changed = False
            for k in names:
                if held[k]:
                    continue
                for j in names:
                    if j == k or not held[j]:
                        continue
                    if np.hypot(*(np.array(mv.axis[j]) - np.array(mv.axis[k]))) > 0.01:
                        continue
                    if kernel.ivol(tr(mv.mob[k], dv), mv.mob[j]) > TOL:
                        held[k] = True
                        changed = True
                        break
        notheld += [(k, dn) for k in names if not held[k]]
    R["2"] = (not notheld, notheld)
    print("2", R["2"], flush=True)
    # 3 seated
    bad = []
    for k in names:
        ps = mv.mparts[k]
        if k == "barrel" or len(ps) < 2:
            continue
        for p in ps:
            others = U(mv.parts[q] for q in ps if q != p)
            for dn in ("+x", "-x", "+y", "-y"):
                v = kernel.ivol(tr(mv.parts[p], dirs[dn]), others)
                if v <= TOL:
                    bad.append((k, p, dn, v))
            vz = [kernel.ivol(tr(mv.parts[p], dirs[dn]), others) for dn in ("+z", "-z")]
            if max(vz) <= TOL:
                bad.append((k, p, "z", vz))
        linked = {ps[0]}
        changed = True
        while changed:
            changed = False
            for p in ps:
                if p in linked:
                    continue
                if any(kernel.min_distance(mv.parts[p], mv.parts[q], 0.05) <= 0.02 for q in linked):
                    linked.add(p)
                    changed = True
        if len(linked) != len(ps):
            bad.append((k, "not one piece"))
    R["3"] = (not bad, bad)
    print("3", R["3"], flush=True)
    # 4, 5 mesh tests
    jobsl = [(fname, cls, i, s) for i in range(len(mv.meshes)) for s in (0.0, 0.03, -0.03)]
    if "5" in skip:
        jobsl = [j for j in jobsl if j[3] == 0.0]
    res = {}
    with ProcessPoolExecutor(jobs) as ex:
        for idx, sh, ok, det in ex.map(_mesh_job, jobsl):
            res[(idx, sh)] = (ok, det)
            e = mv.meshes[idx]
            print("  mesh %s->%s shift %+.2f %s %s" % (e["driver"], e["driven"], sh, ok, det), flush=True)
    passing = {i: res[(i, 0.0)][0] for i in range(len(mv.meshes))}
    sp, conflict = speeds(mv, passing)
    reached = all(k in sp for k in names)
    R["4"] = (all(passing.values()) and not conflict and reached and len(mv.meshes) > 0, (passing, conflict, reached))
    R["5"] = (all(res.get((i, s), (False,))[0] for i in range(len(mv.meshes)) for s in (0.03, -0.03)), None)
